CREATE QUEUE "typed_requests_a" ( ID BIGINT NOT NULL , MACHINE_ID BIGINT NOT NULL , LOOKUP TEXT NOT NULL , BODY TEXT NOT NULL );
CREATE TABLE "typed_machines_a" ( ID BIGINT PRIMARY KEY , LABEL TEXT NOT NULL );
CREATE TABLE "typed_accepted_a" ( ID BIGINT PRIMARY KEY , MACHINE_ID BIGINT NOT NULL , BODY TEXT NOT NULL );
CREATE STREAM "typed_events_a" ( ID BIGINT NOT NULL , MACHINE_ID BIGINT NOT NULL , BODY TEXT NOT NULL );
INSERT INTO "typed_machines_a" VALUES ( 7 , 'ready' );
INSERT INTO "typed_machines_a" VALUES ( 8 , 'duplicate' );
INSERT INTO "typed_machines_a" VALUES ( 9 , 'duplicate' );
CREATE DATAFLOW "typed_process_a" FROM QUEUE "typed_requests_a" AS REQUEST AS BEGIN BEGIN ATOMIC LET FOUND = SELECT ID FROM "typed_machines_a" WHERE LABEL = REQUEST . LOOKUP ; REQUIRE FOUND IS NOT NULL ELSE 'MissingMachine' ; REQUIRE FOUND . ID = REQUEST . MACHINE_ID ELSE 'WrongMachine' ; LET MACHINE = CASE WHEN REQUEST . BODY = 'ready' THEN REQUEST . MACHINE_ID ELSE FOUND . ID END ; LET ID = REQUEST . ID ; INSERT INTO "typed_accepted_a" VALUES ( ID , MACHINE , REQUEST . BODY ) ON CONFLICT ( ID ) DO ASSERT SAME ROW ; REQUIRE REQUEST . BODY <> 'reject' ELSE 'RejectedBody' ; PRODUCE INTO "typed_events_a" VALUES ( ID , MACHINE , REQUEST . BODY ) ; END ; END;
AUTHORIZE DATAFLOW "typed_process_a" AS ROLE CURRENT_ROLE;
ACTIVATE DATAFLOW "typed_process_a";
CREATE QUEUE "typed_requests_b" ( ID BIGINT NOT NULL , MACHINE_ID BIGINT NOT NULL , LOOKUP TEXT NOT NULL , BODY TEXT NOT NULL );
CREATE TABLE "typed_machines_b" ( ID BIGINT PRIMARY KEY , LABEL TEXT NOT NULL );
CREATE TABLE "typed_accepted_b" ( ID BIGINT PRIMARY KEY , MACHINE_ID BIGINT NOT NULL , BODY TEXT NOT NULL );
CREATE STREAM "typed_events_b" ( ID BIGINT NOT NULL , MACHINE_ID BIGINT NOT NULL , BODY TEXT NOT NULL );
