CREATE DATAFLOW "typed_process_b" FROM QUEUE "typed_requests_b" AS REQUEST AS BEGIN BEGIN ATOMIC LET FOUND = SELECT ID FROM "typed_machines_b" WHERE LABEL = REQUEST . LOOKUP ; REQUIRE FOUND IS NOT NULL ELSE 'MissingMachine' ; REQUIRE FOUND . ID = REQUEST . MACHINE_ID ELSE 'WrongMachine' ; LET MACHINE = CASE WHEN REQUEST . BODY = 'ready' THEN REQUEST . MACHINE_ID ELSE FOUND . ID END ; LET ID = REQUEST . ID ; INSERT INTO "typed_accepted_b" VALUES ( ID , MACHINE , REQUEST . BODY ) ON CONFLICT ( ID ) DO ASSERT SAME ROW ; REQUIRE REQUEST . BODY <> 'reject' ELSE 'RejectedBody' ; PRODUCE INTO "typed_events_b" VALUES ( ID , MACHINE , REQUEST . BODY ) ; END ; END;
AUTHORIZE DATAFLOW "typed_process_b" AS ROLE CURRENT_ROLE;
ACTIVATE DATAFLOW "typed_process_b";
